          this.rafId = null;
          return;
        }

        const factor = Math.max(0.01, Math.min(1, this.speed()));
        currentRotX = lerp(currentRotX, targetRotX, factor);
        currentRotY = lerp(currentRotY, targetRotY, factor);
        currentScale = lerp(currentScale, targetScale, factor);

